import {geometry as panelGeometry} from './wall-model.js';
import * as THREE from 'three';
import {OrbitControls} from './vendor/OrbitControls.js';
import {HOLD_LIBRARY,holdDefinition,createHold,disposeHold} from './holds.js';
import {nearestSocket} from './bolt-grid.js';
import {detectHolds} from './hold-detection.js';
const $=s=>document.querySelector(s);
export function createAssistedImport({sectors,defs,holds,getSector,onBegin,onCommit}){
 let si=0,candidates=[],selected=-1,mode='pick',sample=null,plan=[],drag=null,source=null,review3d=false,previewRenderer=null,previewScene,previewCamera,previewControls,previewGroup,renderFrame=0;
 const dialog=document.createElement('dialog');dialog.id='assistedImport';dialog.setAttribute('aria-label','Assisted route import');dialog.innerHTML=`<div class="assist-header"><div><span class="eyebrow">PHOTO → ROUTE</span><h2>Find your line.</h2><p>Pick a hold’s colour, review the suggestions, then build the route.</p></div><button id="assistClose" aria-label="Close assisted import">×</button></div><div class="assist-layout"><section class="assist-image"><div class="assist-tabs"><button id="assistPhotoTab" class="active">Photo & corrections</button><button id="assist3DTab">3D placement preview</button></div><div id="assistPhotoView"><canvas id="assistCanvas" aria-label="Photo with editable hold suggestions"></canvas><p id="assistHint">Click the coloured surface of a route hold to sample its colour.</p></div><div id="assist3DView" hidden><div id="assist3DCanvas"></div><p>Drag to orbit · Scroll to zoom · Only valid suggestions will be imported. Existing holds appear grey.</p></div><div id="assistList" aria-label="Hold suggestions"></div></section><aside class="assist-panel"><span class="eyebrow">1 · CONFIRM SCALE</span><p id="assistDimensions"></p><label class="assist-check"><input type="checkbox" id="assistScaleConfirmed"> The photo is aligned and this wall scale is correct</label><small>To change alignment or wall width, close this window and use the photo controls.</small><hr><span class="eyebrow">2 · FIND HOLDS</span><div class="assist-row"><button id="assistPick">Pick colour</button><input id="assistColour" type="color" value="#d96b4f" aria-label="Route colour"></div><label>Colour tolerance <output id="assistToleranceValue">Medium</output></label><input id="assistTolerance" type="range" min="2" max="18" value="7"><label>Ignore tiny marks <output id="assistMinValue">20 px</output></label><input id="assistMin" type="range" min="5" max="120" value="20"><button id="assistDetect" class="wide dark" disabled>Suggest holds</button><small>Colour-based suggestions run in your browser. Chalk, shadows and similar colours can produce misses or false detections.</small><hr><span class="eyebrow">3 · CORRECT & CHOOSE SHAPES</span><button id="assistAdd" class="wide outline">＋ Add missed hold</button><p class="assist-help">Drag markers to correct positions. Select a marker or numbered chip to edit it.</p><div id="assistSelected" hidden><strong id="assistSelectedTitle"></strong><label>3D shape</label><select id="assistShape"></select><label>Size <output id="assistSizeValue">1.0×</output></label><input id="assistSize" type="range" min="0.5" max="2.3" step="0.05" value="1"><label>Rotation <output id="assistRotationValue">0°</output></label><input id="assistRotation" type="range" min="-180" max="180" step="5" value="0"><button id="assistRemove" class="textbutton">Remove suggestion</button></div><small>Shapes are placeholders, not recognised products. Confirm each shape; depth cannot be recovered from this photo.</small><hr><label class="assist-check"><input id="assistReplace" type="checkbox"> <span id="assistReplaceLabel">Replace existing holds on this wall</span></label><p id="assistStatus" role="status"></p><button id="assistCommit" class="wide dark" disabled>Add reviewed holds</button></aside></div>`;document.body.append(dialog);
 const canvas=$('#assistCanvas'),ctx=canvas.getContext('2d');for(const d of HOLD_LIBRARY){const o=document.createElement('option');o.value=d.id;o.textContent=d.family+' · '+d.name;$('#assistShape').append(o);}
 function rgb(){const hex=$('#assistColour').value;return[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));}
 function prepareImage(){const s=sectors[si],image=s.photo.image,ratio=s.width/defs[si].h;source=document.createElement('canvas');source.width=Math.round(ratio>=1?800:800*ratio);source.height=Math.round(ratio>=1?800/ratio:800);const c=source.getContext('2d'),w=source.width,h=source.height,l=s.photoLayout||{x:0,y:0,scale:1,rotation:0};c.fillStyle=defs[si].color;c.fillRect(0,0,w,h);c.translate(w*(.5+l.x),h*(.5-l.y));c.rotate(-THREE.MathUtils.degToRad(l.rotation));const scale=Math.min(w/image.width,h/image.height)*l.scale;c.drawImage(image,-image.width*scale/2,-image.height*scale/2,image.width*scale,image.height*scale);canvas.width=w;canvas.height=h;}
 function makePlan(){const temporary=[];const occupied=$('#assistReplace').checked?holds.filter(h=>h.userData.si!==si):[...holds],s=sectors[si];plan=candidates.map(c=>{const mesh=createHold(c.type,$('#assistColour').value,c.size);mesh.userData.type=c.type;mesh.rotation.z=THREE.MathUtils.degToRad(c.rotation);const desired=new THREE.Vector3((c.u-.5)*s.width,(1-c.v)*defs[si].h,.132),socket=nearestSocket(sectors,occupied,si,desired,mesh);const delta=socket?socket.position.distanceTo(desired):Infinity;let item={...c,valid:false,reason:'No available fitting bolt hole nearby'};if(socket&&delta<=.42){item={...c,valid:true,x:socket.position.x,y:socket.position.y,socket:socket.id,shift:delta};mesh.position.copy(socket.position);mesh.userData={si,socket:socket.id,type:c.type,size:c.size};occupied.push(mesh);}temporary.push(mesh);return item;});for(const mesh of temporary){disposeHold(mesh);if(mesh.userData.type?.startsWith('volume-'))mesh.geometry.dispose();}
 const good=plan.filter(c=>c.valid).length,bad=plan.length-good;$('#assistStatus').textContent=plan.length?good+' ready · '+bad+' need correction. Positions snap to free bolt holes within 42 cm.':'No suggestions yet. Sample a hold colour, or add markers manually.';$('#assistCommit').disabled=!good||!$('#assistScaleConfirmed').checked;$('#assistCommit').textContent=($('#assistReplace').checked?'Replace wall with ':'Add ')+good+' reviewed hold'+(good===1?'':'s');}
 function draw(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(source,0,0);const radius=Math.max(10,canvas.width*.015);plan.forEach((c,i)=>{const x=c.u*canvas.width,y=c.v*canvas.height;ctx.strokeStyle=c.valid?'#73e7ab':'#ffb16c';ctx.lineWidth=2;if(c.valid){const tx=(c.x/sectors[si].width+.5)*canvas.width,ty=(1-c.y/defs[si].h)*canvas.height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(tx,ty);ctx.stroke();ctx.fillStyle='#73e7ab';ctx.fillRect(tx-3,ty-3,6,6);}ctx.beginPath();ctx.arc(x,y,radius+(i===selected?3:0),0,Math.PI*2);ctx.fillStyle=i===selected?'#fff4dc':'#243c32dc';ctx.fill();ctx.stroke();ctx.fillStyle=i===selected?'#243c32':'#ffffff';ctx.font='600 '+Math.round(radius*1.15)+'px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(i+1,x,y);});}
 function list(){const el=$('#assistList');el.replaceChildren();plan.forEach((c,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.title=(c.valid?'Ready':'Needs correction')+' · '+holdDefinition(c.type).name;b.setAttribute('aria-label','Edit suggestion '+(i+1));b.className=(c.valid?'':'conflict ')+(i===selected?'active':'');b.onclick=()=>{selected=i;showSelected();draw();list();};el.append(b);});}
 function showSelected(){const c=candidates[selected];$('#assistSelected').hidden=!c;if(!c)return;$('#assistSelectedTitle').textContent='Hold '+(selected+1)+(plan[selected]?.valid?'':' · needs correction');$('#assistShape').value=c.type;$('#assistSize').value=c.size;$('#assistSizeValue').value=c.size.toFixed(2)+'×';$('#assistRotation').value=c.rotation;$('#assistRotationValue').value=c.rotation+'°';}
 function refresh(){makePlan();draw();list();showSelected();if(review3d)buildPreview();}
 function setMode(value){mode=value;$('#assistHint').textContent=value==='pick'?'Click inside a route hold to sample its colour.':value==='add'?'Click the centre of a missed hold to add a marker.':'Drag a marker to correct it. Lines point to the proposed bolt holes; orange markers need correction.';canvas.style.cursor=value==='edit'?'grab':'crosshair';}
 function location(e){const r=canvas.getBoundingClientRect();return{u:THREE.MathUtils.clamp((e.clientX-r.left)/r.width,0,1),v:THREE.MathUtils.clamp((e.clientY-r.top)/r.height,0,1)};}
 canvas.onpointerdown=e=>{const p=location(e);if(mode==='pick'){const pixels=source.getContext('2d').getImageData(Math.min(source.width-1,Math.floor(p.u*source.width)),Math.min(source.height-1,Math.floor(p.v*source.height)),1,1).data;sample=[...pixels].slice(0,3);$('#assistColour').value='#'+sample.map(v=>v.toString(16).padStart(2,'0')).join('');$('#assistDetect').disabled=false;setMode('edit');refresh();return;}if(mode==='add'){candidates.push({...p,type:'jug',size:1,rotation:0});selected=candidates.length-1;setMode('edit');refresh();return;}let closest=-1,d=.04;for(let i=0;i<candidates.length;i++){const c=candidates[i],distance=Math.hypot(c.u-p.u,(c.v-p.v)*canvas.height/canvas.width);if(distance<d){closest=i;d=distance;}}if(closest>=0){selected=closest;drag={id:e.pointerId,original:{...candidates[closest]}};canvas.setPointerCapture(e.pointerId);showSelected();draw();list();}};
 canvas.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;Object.assign(candidates[selected],location(e));makePlan();draw();};canvas.onpointerup=e=>{if(!drag)return;drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);refresh();};canvas.onpointercancel=()=>{if(drag){candidates[selected]=drag.original;drag=null;refresh();}};
 $('#assistPick').onclick=()=>{showView(false);setMode('pick');};$('#assistAdd').onclick=()=>{showView(false);setMode('add');};$('#assistColour').oninput=()=>{sample=rgb();$('#assistDetect').disabled=false;refresh();};$('#assistTolerance').oninput=e=>$('#assistToleranceValue').value=e.target.value+' / 18';$('#assistMin').oninput=e=>$('#assistMinValue').value=e.target.value+' px';
 $('#assistDetect').onclick=()=>{const data=source.getContext('2d').getImageData(0,0,source.width,source.height);const found=detectHolds(data.data,source.width,source.height,rgb(),+$('#assistTolerance').value/100,+$('#assistMin').value);candidates=found.map(c=>({...c,type:'jug',size:THREE.MathUtils.clamp(c.w*sectors[si].width/(holdDefinition('jug').w*2),.5,2.3),rotation:0}));selected=candidates.length?0:-1;$('#assistDetect').textContent='Redetect (replaces suggestions)';setMode('edit');refresh();};
 for(const [id,key] of [['assistShape','type'],['assistSize','size'],['assistRotation','rotation']])$('#'+id).oninput=e=>{if(!candidates[selected])return;candidates[selected][key]=key==='type'?e.target.value:+e.target.value;refresh();};$('#assistRemove').onclick=()=>{candidates.splice(selected,1);selected=Math.min(selected,candidates.length-1);refresh();};$('#assistReplace').onchange=refresh;$('#assistScaleConfirmed').onchange=refresh;
 function clearPreview(){if(!previewGroup)return;previewScene.remove(previewGroup);previewGroup.traverse(o=>{if(o.userData.assistHold){disposeHold(o);if(holdDefinition(o.userData.type).family==='Volumes')o.geometry.dispose();}else if(o.isMesh&&!o.parent?.userData.assistHold){o.geometry?.dispose();if(o.material&&!Array.isArray(o.material))o.material.dispose();}});previewGroup=null;}
 function buildPreview(){if(!previewRenderer){previewRenderer=new THREE.WebGLRenderer({antialias:true});previewRenderer.setPixelRatio(Math.min(devicePixelRatio,1.5));previewRenderer.outputColorSpace=THREE.SRGBColorSpace;previewRenderer.toneMapping=THREE.ACESFilmicToneMapping;$('#assist3DCanvas').append(previewRenderer.domElement);previewScene=new THREE.Scene();previewScene.background=new THREE.Color('#e8ebdf');previewScene.add(new THREE.HemisphereLight('#fff8e7','#7d9080',2.7));const light=new THREE.DirectionalLight('#fff9ed',3);light.position.set(-3,7,8);previewScene.add(light);previewCamera=new THREE.PerspectiveCamera(40,1,.01,60);previewControls=new OrbitControls(previewCamera,previewRenderer.domElement);previewControls.enableDamping=true;previewControls.minDistance=2;previewControls.maxDistance=25;}
 clearPreview();const s=sectors[si],height=defs[si].h;previewGroup=new THREE.Group();previewGroup.rotation.x=THREE.MathUtils.degToRad(s.angle);previewScene.add(previewGroup);const wall=new THREE.Mesh(s.config?panelGeometry(s.config):new THREE.BoxGeometry(s.width,height,.25),new THREE.MeshStandardMaterial({color:defs[si].color,roughness:.9}));wall.position.y=s.config?0:height/2;previewGroup.add(wall);
 const add=(c,color)=>{const h=createHold(c.type,color,c.size);h.position.set(c.x,c.y,.132);h.rotation.z=THREE.MathUtils.degToRad(c.rotation);h.userData={assistHold:true,type:c.type};previewGroup.add(h);};if(!$('#assistReplace').checked)for(const h of holds.filter(h=>h.userData.si===si))add({...h.userData,rotation:THREE.MathUtils.radToDeg(h.rotation.z)},'#a7afa3');for(const c of plan.filter(c=>c.valid))add(c,$('#assistColour').value);
 const container=$('#assist3DCanvas'),w=container.clientWidth||600,h=container.clientHeight||480;previewRenderer.setSize(w,h);previewCamera.aspect=w/h;previewCamera.position.set(s.width*.5,height*.7,Math.max(s.width,height)*1.7);previewCamera.updateProjectionMatrix();previewControls.target.set(0,height*.48,0);previewControls.update();}
 new ResizeObserver(()=>{if(review3d&&previewRenderer){const el=$('#assist3DCanvas');previewRenderer.setSize(el.clientWidth,el.clientHeight);previewCamera.aspect=el.clientWidth/el.clientHeight;previewCamera.updateProjectionMatrix();}}).observe($('#assist3DCanvas'));
 function animate(){if(!dialog.open||!review3d){renderFrame=0;return;}renderFrame=requestAnimationFrame(animate);previewControls.update();previewRenderer.render(previewScene,previewCamera);}
 function showView(is3d){review3d=is3d;$('#assistPhotoView').hidden=is3d;$('#assist3DView').hidden=!is3d;$('#assistPhotoTab').classList.toggle('active',!is3d);$('#assist3DTab').classList.toggle('active',is3d);if(is3d){buildPreview();if(!renderFrame)animate();}}
 $('#assistPhotoTab').onclick=()=>showView(false);$('#assist3DTab').onclick=()=>showView(true);$('#assistClose').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(renderFrame)cancelAnimationFrame(renderFrame);renderFrame=0;clearPreview();});dialog.addEventListener('keydown',e=>e.stopPropagation());
 $('#assistCommit').onclick=()=>{makePlan();const ready=plan.filter(c=>c.valid);if(!ready.length||!$('#assistScaleConfirmed').checked)return;onCommit(si,ready,$('#assistColour').value,$('#assistReplace').checked);dialog.close();};
 return{open(){$('#assistShape').replaceChildren(...HOLD_LIBRARY.map(d=>new Option(d.family+' · '+d.name,d.id)));si=getSector();if(!sectors[si].photo)return;onBegin();candidates=[];selected=-1;sample=null;$('#assistScaleConfirmed').checked=false;$('#assistReplace').checked=false;$('#assistDetect').disabled=true;$('#assistDetect').textContent='Suggest holds';$('#assistDimensions').textContent=defs[si].name+' · '+sectors[si].width.toFixed(1)+' m wide × '+defs[si].h.toFixed(1)+' m high · '+sectors[si].angle+'°';$('#assistReplaceLabel').textContent='Replace all '+holds.filter(h=>h.userData.si===si).length+' existing holds on '+defs[si].name;prepareImage();dialog.showModal();showView(false);setMode('pick');refresh();}};
}
